const PROHIBIDO = /\b(websites?|web ?pages?|web ?design|interfaces?|dashboards?|apps?|charts?|graphs?|flow ?charts?|diagrams?|infographics?|whiteboards?|spreadsheets?|clipboards?|checklists?|documents?|paperwork|printed|forms?|signs?|signage|posters?|banners?|billboards?|scoreboards?|menus?|newspapers?|magazines?|catalogu?e?s?|brochures?|flyers?|receipts?|invoices?|price tags?|calendars?|notebooks?|notepads?|project plans?|business plans?|plans? on|text|letters?|lettering|words?|numbers?|meetings?|office)\b/i;
const CON_ETIQUETA = /\b(screens?|monitors?|displays?|laptops?|computers?|tablets?|phones?|smartphones?|cell ?phones?|bottles?|cans?|box(?:es)?|packag\w*|books?|labels?|shelves|shelf|jerseys?|t-?shirts?)\b/i;
// Solo cuenta lo que neutraliza al PRODUCTO. "blurred background" desenfoca el fondo, no la etiqueta
// (botillería de prueba 49, 2026-09-24: "wine bottle ... blurred background" habría salido con etiqueta nítida).
const NEUTRALIZADO = /(facing away|closed|turned off|switched off|dark screen|screen off|unlabell?ed|without (a |any )?labels?|plain|blank|from behind|seen from the back)/i;
const FONDO_PORTADA = /\b(stadiums?|facades?|storefronts?|shop ?fronts?|exteriors?|buildings?|streets?|walls?|billboards?|bleachers?|grandstands?)\b/i;
const PRIMER_PLANO = /(close-?up|macro|shallow depth of field|bokeh|blurred background|background (completely )?blurred)/i;
const CIERRE = 'no signs, no labels, no text, no lettering, no logos, no watermarks';
const NEGATIVAS = /[,.;]?\s*\b(?:no|without)\b(?:\s+any)?[^,.;]*?\b(?:people facing camera|screens?|signs?|signage|labels?|text|lettering|logos?|words?|watermarks?|writing)\b[^,.;]*/gi;
const SEGURAS = {
  cover: 'close-up of warm morning light falling across a textured wooden surface with a small green plant, background completely blurred into soft golden bokeh, shallow depth of field',
  challenge: 'quiet empty room at night lit by a single warm lamp, rain drops on a large window, calm pensive mood',
  solution: 'bright calm space with natural light through tall windows and a green plant, soft morning light',
  benefits: 'wide open landscape of the Chilean central valley at sunrise with the Andes in the distance, soft golden light',
  how_it_works: 'close-up of hands arranging small wooden blocks in a neat row on a light table, soft daylight, shallow depth of field',
  pricing: 'close-up of a single green sprout growing from rich dark soil in soft morning light, shallow depth of field',
  next_steps: 'open country road through green hills at sunrise, soft mist, hopeful calm atmosphere',
  extra: 'soft pattern of light and shadow on a textured surface next to a small plant, calm minimal composition',
};
// GPT-4o escribe escenas del rubro ("hand holding a wine bottle") pero no agrega "sin etiqueta" aunque se le
// pida (Borrador 403817, 2026-09-24). En vez de perder la escena, el filtro la neutraliza: producto sin etiqueta,
// pantallas apagadas y de espaldas. Si aun así queda algo sin neutralizar, se reemplaza.
const PRODUCTO = /\b((?:(?:wine|beer|liquor|whisky|whiskey|pisco|vodka|gin|rum|glass|plastic|cardboard|gift|delivery)\s+)?(?:bottles?|cans?|jars?|box(?:es)?|packages?|parcels?|books?|jerseys?|t-?shirts?))\b/gi;
const PANTALLA = /\b(screens?|monitors?|displays?|laptops?|computers?|tablets?|phones?|smartphones?|cell ?phones?)\b/i;
function neutralizar(tema) {
  if (!CON_ETIQUETA.test(tema) || NEUTRALIZADO.test(tema)) return tema;
  let t = tema.replace(/\s*with (?:its|a|the|their) labels?/gi, '').replace(PRODUCTO, 'plain unlabeled $1');
  if (PANTALLA.test(t)) t += ', every screen dark and facing away from the camera';
  if (/\b(shelves|shelf)\b/i.test(t) && !/unlabell?ed/i.test(t)) t += ', shelves holding only plain unlabeled products';
  return t;
}
function motivoFoto(slide, tema) {
  if (!tema) return 'vacía';
  if (PROHIBIDO.test(tema)) return 'texto o pantalla';
  if (slide === 'cover' && FONDO_PORTADA.test(tema)) return 'portada con estructuras de fondo';
  if (CON_ETIQUETA.test(tema) && !NEUTRALIZADO.test(tema)) return 'producto con etiqueta o pantalla visible';
  return '';
}
function limpiarFotos(briefs) {
  let reemplazadas = 0;
  let neutralizadas = 0;
  const limpias = (briefs || []).filter((b) => b && b.slide).map((b) => {
    // Se descarta la lista de prohibiciones que haya escrito el modelo: el cierre lo pone siempre el filtro.
    // Cualquier forma: ", no text", ". No signs", "without any text or signage" (revisión final 2026-09-24, M5:
    // antes solo se cortaba ", no …" y una escena buena caía en PROHIBIDO por su propia prohibición).
    const original = String(b.prompt || '').replace(NEGATIVAS, '').trim().replace(/[\s,.;]+$/, '');
    let tema = neutralizar(original);
    if (motivoFoto(b.slide, tema)) {
      reemplazadas++;
      tema = SEGURAS[b.slide] || SEGURAS.extra;
    } else if (tema !== original) {
      neutralizadas++;
    }
    if (b.slide === 'cover' && !PRIMER_PLANO.test(tema)) {
      tema += ', close-up, shallow depth of field, background completely blurred';
    }
    return { slide: b.slide, prompt: `${tema}, ${CIERRE}` };
  });
  return { limpias, reemplazadas, neutralizadas };
}

// Último filtro antes de gastar: no guarda nada, solo decide qué fotos se le piden al renderer.
// Solo láminas que existen y una foto por lámina: Cambios puede dejar briefs de extras borradas o repetidos,
// y cada uno se paga (revisión final 2026-09-24, M6). Nunca lanza: sin payload el renderer contesta 400 y
// Verificar deja la propuesta en «error» en vez de trabada en «generando» (I1).
const e = $('Leer estado').first().json.body || {};
const p = e.payload && typeof e.payload === 'object' ? e.payload : {};
const extras = Math.min(Array.isArray(p.extra_slides) ? p.extra_slides.length : 0, 2);
const validas = new Set(['cover', 'challenge', 'solution', 'benefits', 'how_it_works', 'pricing', 'next_steps',
  ...Array.from({ length: extras }, (_, i) => `extra_${i + 1}`)]);
const vistas = new Set();
const briefs = (Array.isArray(p.image_briefs) ? p.image_briefs : [])
  .filter((b) => b && validas.has(b.slide) && !vistas.has(b.slide) && vistas.add(b.slide));
const r = limpiarFotos(briefs);
return [{ json: { unique_id: e.unique_id, payload: Object.assign({}, p, { image_briefs: r.limpias }), fotos_reemplazadas: r.reemplazadas } }];

// Tras cada render: si faltan fotos o no hubo presentación, se vuelve a llamar al renderer.
// El renderer reutiliza las fotos ya guardadas con el mismo prompt (manifest.json) y solo pide las que faltan,
// así que un reintento no vuelve a pagar las que ya salieron. Tope: MAX_RENDERS llamadas.
const MAX_RENDERS = 3;
const r = $json || {};
const faltan = !r.view_url || ((r.images && r.images.missing) || []).length > 0;
const intento = $runIndex + 1;
const base = $('Revisar fotos').first().json;
return [{ json: Object.assign({}, base, { reintentar: faltan && intento < MAX_RENDERS, intento }) }];

// Junta las verificaciones. Nada aquí lanza: el resultado decide «lista» o «error».
const est = $('Leer estado').first().json.body;
// Sin runIndex, $('Render final') devuelve la ÚLTIMA pasada del bucle de reintentos.
const r = $('Render final').first().json || {};
const img = r.images || {};
const renders = $('¿Reintentar render?').first().json.intento;
const problemas = [];
if (!r.view_url) problemas.push('el renderer no devolvió la presentación' + (r.error ? ` (${r.error.message || r.error})` : ''));
if ((img.missing || []).length) problemas.push(`fotos que no se generaron tras ${renders} intentos: ${img.missing.join(', ')}`);
if ((img.kept_remote || []).length) problemas.push(`fotos que no se pudieron guardar en local: ${img.kept_remote.join(', ')}`);
const pres = $('Ver presentación').first().json;
if (pres.statusCode !== 200) problemas.push(`ver-presentacion respondió ${pres.statusCode}`);
const pdf = $('PDF').first().json;
if (pdf.statusCode !== 200) problemas.push(`el PDF respondió ${pdf.statusCode}`);
const chat = $('Probar chatbot').first().json;
const respuesta = chat.body && chat.body.output ? String(chat.body.output) : '';
if (chat.statusCode !== 200 || !respuesta) problemas.push(`el chatbot de demo no respondió (HTTP ${chat.statusCode})`);
const ok = problemas.length === 0;
return [{ json: {
  ok, problemas, id: est.id, unique_id: est.unique_id, company: est.company_name,
  fotos_locales: img.stored_local || 0, fotos_pedidas: img.requested || 0,
  chat_respuesta: respuesta.slice(0, 300),
  note: ok ? `Verificada: presentación, PDF, ${img.stored_local || 0} fotos locales (${renders} render${renders === 1 ? '' : 's'}) y chatbot OK` : problemas.join(' · '),
} }];

// Falló la lectura del estado: no hay payload que renderizar.
const hook = $('Webhook').first().json.body || {};
const le = $('Leer estado').first().json;
return [{ json: { ok: false, id: hook.id, unique_id: '', company: `propuesta ${hook.id}`,
  problemas: [`No se pudo leer la propuesta en WordPress (HTTP ${le.statusCode})`],
  note: `No se pudo leer la propuesta en WordPress (HTTP ${le.statusCode})`, fotos_locales: 0, fotos_pedidas: 0, chat_respuesta: '' } }];

const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const br = (s) => esc(s).replace(/\n/g, '<br>');
const v = $('Verificar').isExecuted ? $('Verificar').first().json : $('Motivo lectura').first().json;
const g = $('Guardar resultado').first().json;
const rev = $('Revisar fotos').isExecuted ? $('Revisar fotos').first().json.fotos_reemplazadas : 0;
const ok = v.ok;
const li = (t) => `<li style="margin:0 0 6px;">${t}</li>`;
const html = `<div style="margin:0;padding:24px 12px;background:#eef2f6;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;margin:0 auto;background:#ffffff;border-radius:14px;overflow:hidden;box-shadow:0 2px 10px rgba(13,27,42,.08);">
<tr><td style="background:#0d1b2a;padding:18px 24px;">
<table role="presentation" cellpadding="0" cellspacing="0"><tr>
<td style="vertical-align:middle;"><img src="https://automatizatech.cl/wp-content/themes/automatiza-tech/assets/images/logo-automatiza-tech.png" width="44" height="37" alt="AutomatizaTech" style="display:block;border:0;"></td>
<td style="vertical-align:middle;padding-left:12px;font-family:Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#ffffff;font-size:16px;font-weight:700;">AutomatizaTech<br><span style="color:#00d9c0;font-size:12px;font-weight:600;letter-spacing:.04em;">Propuestas · aviso interno</span></td>
</tr></table>
</td></tr>
<tr><td style="height:4px;background:#00d9c0;line-height:4px;font-size:0;">&nbsp;</td></tr>
<tr><td style="padding:26px 24px 8px;">
${ok ? `<span style="display:inline-block;background:#dcfce7;color:#166534;font-family:Segoe UI,Roboto,Helvetica,Arial,sans-serif;font-size:12px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;padding:5px 12px;border-radius:999px;">Lista para enviar</span>` : `<span style="display:inline-block;background:#fee2e2;color:#991b1b;font-family:Segoe UI,Roboto,Helvetica,Arial,sans-serif;font-size:12px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;padding:5px 12px;border-radius:999px;">Con problemas</span>`}
<h1 style="margin:14px 0 16px;font-family:Segoe UI,Roboto,Helvetica,Arial,sans-serif;font-size:22px;line-height:1.3;color:#0d1b2a;">${ok ? 'Lista para enviar' : 'La versión final tiene problemas'}: ${esc(v.company)}</h1>
${g.statusCode === 200 ? '' : `<div style="background:#fef2f2;border-left:4px solid #ef4444;border-radius:8px;padding:14px 16px;margin:0 0 16px;font-family:Segoe UI,Roboto,Helvetica,Arial,sans-serif;font-size:14px;line-height:1.55;color:#334155;"><strong>No se pudo guardar el resultado en WordPress</strong> (HTTP ${esc(g.statusCode)}): la propuesta puede seguir en «generando». Revísala en el panel.</div>`}${ok ? `<div style="background:#f0fdf4;border-left:4px solid #22c55e;border-radius:8px;padding:14px 16px;margin:0 0 16px;font-family:Segoe UI,Roboto,Helvetica,Arial,sans-serif;font-size:14px;line-height:1.55;color:#334155;"><ul style="margin:0;padding-left:18px;">${li("Presentación publicada y accesible")}${li("PDF generado")}${li(esc(v.fotos_locales) + " de " + esc(v.fotos_pedidas) + " fotos guardadas junto a la presentación")}${rev ? li(esc(rev) + " descripciones de fotos reemplazadas por el filtro (pedían pantallas, texto o personas)") : ""}${li("El chatbot de demo respondió")}</ul></div>` : `<div style="background:#fef2f2;border-left:4px solid #ef4444;border-radius:8px;padding:14px 16px;margin:0 0 16px;font-family:Segoe UI,Roboto,Helvetica,Arial,sans-serif;font-size:14px;line-height:1.55;color:#334155;"><ul style="margin:0;padding-left:18px;">${(v.problemas || []).map((p) => li(esc(p))).join("")}</ul></div><p style="margin:0 0 14px;font-family:Segoe UI,Roboto,Helvetica,Arial,sans-serif;font-size:15px;line-height:1.55;color:#334155;">La propuesta quedó en <strong>error</strong>: desde el panel puedes volver a aprobarla o pedir cambios.</p>`}${v.chat_respuesta ? `<p style="margin:0 0 14px;font-family:Segoe UI,Roboto,Helvetica,Arial,sans-serif;font-size:15px;line-height:1.55;color:#334155;"><strong>El chatbot respondió a «Hola»:</strong></p><div style="background:#f8fafc;border-left:4px solid #cbd5e1;border-radius:8px;padding:14px 16px;margin:0 0 16px;font-family:Segoe UI,Roboto,Helvetica,Arial,sans-serif;font-size:14px;line-height:1.55;color:#334155;">${br(v.chat_respuesta)}</div>` : ''}<div style="margin:6px 0 4px;">${v.unique_id ? `<a href="https://automatizatech.cl/ver-presentacion.php?id=${esc(v.unique_id)}" style="display:inline-block;background:#00d9c0;color:#0d1b2a;border:2px solid #00d9c0;font-family:Segoe UI,Roboto,Helvetica,Arial,sans-serif;font-size:15px;font-weight:700;text-decoration:none;padding:12px 22px;border-radius:10px;margin:6px 8px 6px 0;">📊 Ver la presentación final</a>` : ''}<a href="https://automatizatech.cl/wp-admin/admin.php?page=automatiza-proposals&edit_id=${esc(v.id)}" style="display:inline-block;background:#ffffff;color:#0d1b2a;border:2px solid #0d1b2a;font-family:Segoe UI,Roboto,Helvetica,Arial,sans-serif;font-size:15px;font-weight:700;text-decoration:none;padding:12px 22px;border-radius:10px;margin:6px 8px 6px 0;">✏️ Abrir en el panel</a></div><p style="margin:18px 0 0;font-family:Segoe UI,Roboto,Helvetica,Arial,sans-serif;font-size:13px;line-height:1.5;color:#64748b;">El PDF se descarga desde la última lámina. El envío al cliente lo haces tú desde el panel, con la casilla «Enviar correo».</p>
</td></tr>
<tr><td style="padding:14px 24px 22px;border-top:1px solid #e2e8f0;font-family:Segoe UI,Roboto,Helvetica,Arial,sans-serif;font-size:12px;line-height:1.5;color:#64748b;">
Aviso automático del flujo de propuestas de AutomatizaTech. Nada de esto se envía al cliente: el envío lo haces tú desde el panel.
</td></tr>
</table>
</div>`;
return [{ json: { asunto: (ok ? '✅ ' : '⚠️ ') + v.company + (ok ? ' · lista para enviar' : ' · la versión final tiene problemas'), html } }];
